import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.em2JOrjF.js";const p=JSON.parse('{"title":"All Sheets — Column Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/schema/sheets.md","filePath":"reference/schema/sheets.md"}'),c={name:"reference/schema/sheets.md"};function a(s,t,n,i,l,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="all-sheets-—-column-reference" tabindex="-1">All Sheets — Column Reference <a class="header-anchor" href="#all-sheets-—-column-reference" aria-label="Permalink to &quot;All Sheets — Column Reference&quot;">​</a></h1><p>Full column definitions for every tab in the database sheet. Columns are listed in order — the index (0-based) is the positional contract the bot uses.</p><blockquote><p><strong>Warning</strong>: Column order is the code contract. Never reorder or insert columns in the middle. See <a href="/vera-docs/reference/schema/">Schema Overview</a>.</p></blockquote><hr><h2 id="_01-time-entries-—-a-h" tabindex="-1">01. Time Entries — <code>A:H</code> <a class="header-anchor" href="#_01-time-entries-—-a-h" aria-label="Permalink to &quot;01. Time Entries — `A:H`&quot;">​</a></h2><p><strong>Written by</strong>: <code>log_time</code>, <code>log_sick_day</code>, <code>log_leave</code>, <code>approve_pto</code>, <code>approve_time_off</code><strong>Updated by</strong>: <code>edit_entry</code> (full row rewrite A:H) <strong>Deleted by</strong>: <code>delete_entry</code></p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential, permanent. Never reused.</td></tr><tr><td>B</td><td>1</td><td><code>date</code></td><td><code>YYYY-MM-DD</code></td><td>Entry date (not necessarily today).</td></tr><tr><td>C</td><td>2</td><td><code>person</code></td><td>string</td><td><strong>Deprecated</strong> — always <code>&quot;&quot;</code>. Do not read.</td></tr><tr><td>D</td><td>3</td><td><code>user_id</code></td><td>integer</td><td>FK → <code>03. Users.id</code></td></tr><tr><td>E</td><td>4</td><td><code>project_id</code></td><td>integer</td><td>FK → <code>02. Projects.id</code></td></tr><tr><td>F</td><td>5</td><td><code>task_id</code></td><td>integer or <code>&quot;&quot;</code></td><td>FK → <code>05. Tasks.id</code>. Empty for sick/leave/PTO entries.</td></tr><tr><td>G</td><td>6</td><td><code>hours</code></td><td>float</td><td>Decimal hours, e.g. <code>4.5</code></td></tr><tr><td>H</td><td>7</td><td><code>notes</code></td><td>string</td><td>Optional. Labels: <code>&quot;Sick day&quot;</code>, <code>&quot;Leave&quot;</code>, <code>&quot;PTO&quot;</code>.</td></tr></tbody></table><p><strong>Example</strong>: <code>101, 2026-03-14, , 5, 12, 3, 2.5, Development work</code></p><hr><h2 id="_02-projects-—-a-l" tabindex="-1">02. Projects — <code>A:L</code> <a class="header-anchor" href="#_02-projects-—-a-l" aria-label="Permalink to &quot;02. Projects — `A:L`&quot;">​</a></h2><p><strong>Written by</strong>: <code>create_project</code>, <code>create_sprint</code>, <code>ensureProtectedProjects</code><strong>Updated by</strong>: <code>set_project_budget</code> (D), <code>set_project_deadline</code> (I), <code>rename_project</code> (B), <code>assign_pm</code> (G), <code>update_sprint_status</code> (L) <strong>Deleted by</strong>: <code>delete_project</code></p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential, permanent.</td></tr><tr><td>B</td><td>1</td><td><code>name</code></td><td>string</td><td>Unique per tenant.</td></tr><tr><td>C</td><td>2</td><td><code>client_id</code></td><td>integer</td><td>FK → <code>04. Clients.id</code></td></tr><tr><td>D</td><td>3</td><td><code>budget_hours</code></td><td>float or <code>&quot;&quot;</code></td><td>Total hours cap. Set via <code>set_project_budget</code>.</td></tr><tr><td>E</td><td>4</td><td><code>alert_threshold</code></td><td>integer</td><td>Percent 0–100. Default <code>80</code>.</td></tr><tr><td>F</td><td>5</td><td><code>status</code></td><td>string</td><td><code>&quot;active&quot;</code> or <code>&quot;inactive&quot;</code> (lowercase).</td></tr><tr><td>G</td><td>6</td><td><code>pm_user_id</code></td><td>integer or <code>&quot;&quot;</code></td><td>FK → <code>03. Users.id</code>. Set via <code>assign_pm</code>.</td></tr><tr><td>H</td><td>7</td><td><code>project_category</code></td><td>string</td><td><code>&quot;client&quot;</code> | <code>&quot;internal&quot;</code> | <code>&quot;pto&quot;</code> | <code>&quot;sick&quot;</code> | <code>&quot;leave&quot;</code> | <code>&quot;time_off&quot;</code></td></tr><tr><td>I</td><td>8</td><td><code>deadline</code></td><td><code>YYYY-MM-DD</code> or <code>&quot;&quot;</code></td><td>Owner-only via <code>set_project_deadline</code>.</td></tr><tr><td>J</td><td>9</td><td><code>parent_project_id</code></td><td>integer or <code>&quot;&quot;</code></td><td>Sprints only. FK → <code>02. Projects.id</code>.</td></tr><tr><td>K</td><td>10</td><td><code>sprint_number</code></td><td>integer or <code>&quot;&quot;</code></td><td>Sprints only. Auto-incremented.</td></tr><tr><td>L</td><td>11</td><td><code>sprint_status</code></td><td>string or <code>&quot;&quot;</code></td><td>Sprints only: <code>&quot;planned&quot;</code> | <code>&quot;active&quot;</code></td></tr></tbody></table><p><strong>Example</strong>: <code>42, Nike Rebrand, 7, 200, 80, active, 3, client, 2026-06-30, , , </code></p><hr><h2 id="_03-users-—-a-h" tabindex="-1">03. Users — <code>A:H</code> <a class="header-anchor" href="#_03-users-—-a-h" aria-label="Permalink to &quot;03. Users — `A:H`&quot;">​</a></h2><p><strong>Written by</strong>: <code>add_user</code>, <code>ensure_user</code><strong>Updated by</strong>: <code>update_user_role</code> (D), <code>rename_user</code> (C), <code>deactivate_user</code> (E), <code>reactivate_user</code> (E)</p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential, permanent.</td></tr><tr><td>B</td><td>1</td><td><code>slack_user_id</code></td><td>string</td><td>Slack user ID, e.g. <code>U01234567</code>.</td></tr><tr><td>C</td><td>2</td><td><code>name</code></td><td>string</td><td>Display name.</td></tr><tr><td>D</td><td>3</td><td><code>role</code></td><td>string</td><td><code>&quot;owner&quot;</code> | <code>&quot;manager&quot;</code> | <code>&quot;user&quot;</code>. Code normalises <code>&quot;pm&quot;</code> → <code>&quot;manager&quot;</code> on read.</td></tr><tr><td>E</td><td>4</td><td><code>status</code></td><td>string</td><td><code>&quot;active&quot;</code> | <code>&quot;inactive&quot;</code></td></tr><tr><td>F</td><td>5</td><td><code>discipline_id</code></td><td>integer or <code>&quot;&quot;</code></td><td>FK → <code>08. Disciplines.id</code></td></tr><tr><td>G</td><td>6</td><td><code>employment_type</code></td><td>string</td><td><code>&quot;fte&quot;</code> | <code>&quot;contractor&quot;</code> | <code>&quot;vendor&quot;</code></td></tr><tr><td>H</td><td>7</td><td><code>hours_per_week</code></td><td>float</td><td>Working hours per week. Default <code>40</code>. Set explicitly for contractors. Used for capacity and overbooking calculations. Vendor value is a placeholder only.</td></tr></tbody></table><p><strong>Example</strong>: <code>5, U01234567, Sarah Chen, manager, active, 2, fte, 40</code></p><hr><h2 id="_04-clients-—-a-d" tabindex="-1">04. Clients — <code>A:D</code> <a class="header-anchor" href="#_04-clients-—-a-d" aria-label="Permalink to &quot;04. Clients — `A:D`&quot;">​</a></h2><p><strong>Written by</strong>: <code>create_client</code>, <code>create_project</code> (auto-creates client), <code>ensureProtectedProjects</code> (auto-creates &quot;Internal&quot;)</p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential.</td></tr><tr><td>B</td><td>1</td><td><code>name</code></td><td>string</td><td>Unique. <code>&quot;Internal&quot;</code> is auto-created.</td></tr><tr><td>C</td><td>2</td><td><code>status</code></td><td>string</td><td><code>&quot;active&quot;</code> | <code>&quot;inactive&quot;</code></td></tr><tr><td>D</td><td>3</td><td><code>notes</code></td><td>string</td><td>Optional. Column D has no header in the sheet.</td></tr></tbody></table><p><strong>Example</strong>: <code>3, Acme Corp, active, Enterprise client</code></p><hr><h2 id="_05-tasks-—-a-c" tabindex="-1">05. Tasks — <code>A:C</code> <a class="header-anchor" href="#_05-tasks-—-a-c" aria-label="Permalink to &quot;05. Tasks — `A:C`&quot;">​</a></h2><p><strong>Written by</strong>: <code>create_task</code></p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential.</td></tr><tr><td>B</td><td>1</td><td><code>name</code></td><td>string</td><td>e.g. <code>&quot;Development&quot;</code>, <code>&quot;Design&quot;</code>, <code>&quot;QA&quot;</code></td></tr><tr><td>C</td><td>2</td><td><code>is_billable</code></td><td>boolean string</td><td><code>&quot;TRUE&quot;</code> or <code>&quot;FALSE&quot;</code></td></tr></tbody></table><p><strong>Example</strong>: <code>3, Development, TRUE</code></p><hr><h2 id="_06-project-tasks-—-a-d" tabindex="-1">06. Project_Tasks — <code>A:D</code> <a class="header-anchor" href="#_06-project-tasks-—-a-d" aria-label="Permalink to &quot;06. Project_Tasks — `A:D`&quot;">​</a></h2><p><strong>Written by</strong>: <code>enable_task_for_project</code> — writes <code>[project_id, task_id, budget_hours, alert_threshold]</code><strong>Deleted by</strong>: <code>disable_task_for_project</code> (row deletion), <code>delete_project</code> (cascade)</p><blockquote><p><strong>Presence = enabled.</strong> A row here means the task is enabled for that project. Absence means disabled. There is no <code>enabled</code> flag column — the CLAUDE.md documentation is incorrect on this point.</p></blockquote><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>project_id</code></td><td>integer</td><td>FK → <code>02. Projects.id</code></td></tr><tr><td>B</td><td>1</td><td><code>task_id</code></td><td>integer</td><td>FK → <code>05. Tasks.id</code></td></tr><tr><td>C</td><td>2</td><td><code>budget_hours</code></td><td>float or <code>&quot;&quot;</code></td><td>Task-level hours budget. Empty if none set.</td></tr><tr><td>D</td><td>3</td><td><code>alert_threshold</code></td><td>integer</td><td>Percent. Default <code>80</code>.</td></tr></tbody></table><p><strong>Example</strong>: <code>42, 3, 40, 80</code></p><hr><h2 id="_07-budgets-allocations-envelopes-—-a-i" tabindex="-1">07. Budgets (Allocations / Envelopes) — <code>A:I</code> <a class="header-anchor" href="#_07-budgets-allocations-envelopes-—-a-i" aria-label="Permalink to &quot;07. Budgets (Allocations / Envelopes) — `A:I`&quot;">​</a></h2><p><strong>Written by</strong>: <code>allocate_hours</code><strong>Updated by</strong>: <code>update_allocation</code> (D, F), <code>cancel_allocation</code> (F)</p><blockquote><p>Despite the name, this sheet stores <strong>per-person hour envelopes</strong> (allocations), not project budgets. The project-level budget lives in <code>02. Projects.budget_hours</code>.</p></blockquote><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential.</td></tr><tr><td>B</td><td>1</td><td><code>user_id</code></td><td>integer</td><td>FK → <code>03. Users.id</code></td></tr><tr><td>C</td><td>2</td><td><code>project_id</code></td><td>integer</td><td>FK → <code>02. Projects.id</code></td></tr><tr><td>D</td><td>3</td><td><code>allocated_hours</code></td><td>float</td><td>Hours for this person on this project.</td></tr><tr><td>E</td><td>4</td><td><code>transferred_from_allocation_id</code></td><td>integer or <code>&quot;&quot;</code></td><td>FK → <code>07. Budgets.id</code>. Set when transferred; <code>&quot;&quot;</code> on initial creation.</td></tr><tr><td>F</td><td>5</td><td><code>status</code></td><td>string</td><td><code>&quot;active&quot;</code> | <code>&quot;cancelled&quot;</code></td></tr><tr><td>G</td><td>6</td><td><code>created_by</code></td><td>integer</td><td>FK → <code>03. Users.id</code> — the Manager/Owner who created it.</td></tr><tr><td>H</td><td>7</td><td><code>created_at</code></td><td><code>YYYY-MM-DD</code></td><td>Creation date.</td></tr><tr><td>I</td><td>8</td><td><code>task_id</code></td><td>integer or <code>&quot;&quot;</code></td><td>FK → <code>05. Tasks.id</code>. Optional work-category tag.</td></tr></tbody></table><p><strong>Example</strong>: <code>17, 5, 42, 40, , active, 2, 2026-03-10, 3</code></p><hr><h2 id="_08-disciplines-—-a-c" tabindex="-1">08. Disciplines — <code>A:C</code> <a class="header-anchor" href="#_08-disciplines-—-a-c" aria-label="Permalink to &quot;08. Disciplines — `A:C`&quot;">​</a></h2><p><strong>Written by</strong>: <code>add_discipline</code></p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential.</td></tr><tr><td>B</td><td>1</td><td><code>name</code></td><td>string</td><td>e.g. <code>&quot;Engineering&quot;</code>, <code>&quot;Design&quot;</code></td></tr><tr><td>C</td><td>2</td><td><code>status</code></td><td>string</td><td>Always <code>&quot;active&quot;</code>.</td></tr></tbody></table><p><strong>Example</strong>: <code>2, Design, active</code></p><hr><h2 id="_09-conversations-—-a-f" tabindex="-1">09. Conversations — <code>A:F</code> <a class="header-anchor" href="#_09-conversations-—-a-f" aria-label="Permalink to &quot;09. Conversations — `A:F`&quot;">​</a></h2><p><strong>Written by</strong>: <code>store_conversation</code> (auto-called after every exchange) <strong>Read by</strong>: <code>get_conversation</code> (returns last N exchanges for current user today)</p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>conversation_id</code></td><td>string</td><td>Composite: <code>{slack_user_id}_{YYYY-MM-DD}</code></td></tr><tr><td>B</td><td>1</td><td><code>timestamp</code></td><td>ISO 8601</td><td>Full timestamp.</td></tr><tr><td>C</td><td>2</td><td><code>user_id</code></td><td>string</td><td>Slack user ID (string, not integer DB id).</td></tr><tr><td>D</td><td>3</td><td><code>user_name</code></td><td>string</td><td>Display name at time of message.</td></tr><tr><td>E</td><td>4</td><td><code>message</code></td><td>string</td><td>The user&#39;s message.</td></tr><tr><td>F</td><td>5</td><td><code>response</code></td><td>string</td><td>VERA&#39;s response.</td></tr></tbody></table><p>One row per exchange. Only today&#39;s rows are read (24-hour context window).</p><hr><h2 id="_10-pending-pto-—-a-i" tabindex="-1">10. Pending_PTO — <code>A:I</code> <a class="header-anchor" href="#_10-pending-pto-—-a-i" aria-label="Permalink to &quot;10. Pending_PTO — `A:I`&quot;">​</a></h2><p><strong>Written by</strong>: <code>request_pto</code><strong>Updated by</strong>: <code>approve_pto</code> (status, approved_by, resolved_at)</p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential.</td></tr><tr><td>B</td><td>1</td><td><code>user_id</code></td><td>integer</td><td>FK → <code>03. Users.id</code></td></tr><tr><td>C</td><td>2</td><td><code>date</code></td><td><code>YYYY-MM-DD</code></td><td>Requested date.</td></tr><tr><td>D</td><td>3</td><td><code>hours</code></td><td>float</td><td>Typically 8h (one work day).</td></tr><tr><td>E</td><td>4</td><td><code>status</code></td><td>string</td><td><code>&quot;pending&quot;</code> | <code>&quot;approved&quot;</code> | <code>&quot;rejected&quot;</code></td></tr><tr><td>F</td><td>5</td><td><code>created_at</code></td><td><code>YYYY-MM-DD</code></td><td>When submitted.</td></tr><tr><td>G</td><td>6</td><td><code>approved_by</code></td><td>integer or <code>&quot;&quot;</code></td><td>FK → <code>03. Users.id</code>. Set on resolution.</td></tr><tr><td>H</td><td>7</td><td><code>resolved_at</code></td><td><code>YYYY-MM-DD</code> or <code>&quot;&quot;</code></td><td>When approved/rejected.</td></tr><tr><td>I</td><td>8</td><td><code>notes</code></td><td>string</td><td>User-supplied reason.</td></tr></tbody></table><p><strong>Example</strong>: <code>8, 5, 2026-03-20, 8, approved, 2026-03-14, 2, 2026-03-14, Holiday trip</code></p><hr><h2 id="_11-unresolved-items-—-a-i" tabindex="-1">11. Unresolved_Items — <code>A:I</code> <a class="header-anchor" href="#_11-unresolved-items-—-a-i" aria-label="Permalink to &quot;11. Unresolved_Items — `A:I`&quot;">​</a></h2><p><strong>Written by</strong>: <code>createUnresolvedItem()</code> — called by <code>log_sick_day</code>, <code>log_leave</code>, <code>approve_pto</code>, <code>request_time_off</code><strong>Updated by</strong>: <code>resolve_item</code>, <code>dismiss_item</code> (G:I)</p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential.</td></tr><tr><td>B</td><td>1</td><td><code>type</code></td><td>string</td><td><code>&quot;sick_conflict&quot;</code> | <code>&quot;leave_conflict&quot;</code> | <code>&quot;pto_conflict&quot;</code> | <code>&quot;time_off_request&quot;</code></td></tr><tr><td>C</td><td>2</td><td><code>description</code></td><td>string</td><td>Human-readable, or JSON for <code>time_off_request</code> type.</td></tr><tr><td>D</td><td>3</td><td><code>affected_project_id</code></td><td>integer or <code>&quot;&quot;</code></td><td>FK → <code>02. Projects.id</code></td></tr><tr><td>E</td><td>4</td><td><code>affected_user_id</code></td><td>integer or <code>&quot;&quot;</code></td><td>FK → <code>03. Users.id</code></td></tr><tr><td>F</td><td>5</td><td><code>created_at</code></td><td><code>YYYY-MM-DD</code></td><td></td></tr><tr><td>G</td><td>6</td><td><code>status</code></td><td>string</td><td><code>&quot;open&quot;</code> | <code>&quot;resolved&quot;</code> | <code>&quot;dismissed&quot;</code></td></tr><tr><td>H</td><td>7</td><td><code>resolved_at</code></td><td><code>YYYY-MM-DD</code> or <code>&quot;&quot;</code></td><td></td></tr><tr><td>I</td><td>8</td><td><code>resolved_by</code></td><td>integer or <code>&quot;&quot;</code></td><td>FK → <code>03. Users.id</code></td></tr></tbody></table><hr><h2 id="_12-company-calendar-—-a-d" tabindex="-1">12. Company_Calendar — <code>A:D</code> <a class="header-anchor" href="#_12-company-calendar-—-a-d" aria-label="Permalink to &quot;12. Company_Calendar — `A:D`&quot;">​</a></h2><p><strong>Written by</strong>: <code>add_company_holiday</code><strong>Deleted by</strong>: <code>remove_company_holiday</code></p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential.</td></tr><tr><td>B</td><td>1</td><td><code>date</code></td><td><code>YYYY-MM-DD</code></td><td></td></tr><tr><td>C</td><td>2</td><td><code>name</code></td><td>string</td><td>e.g. <code>&quot;Christmas Day&quot;</code></td></tr><tr><td>D</td><td>3</td><td><code>type</code></td><td>string</td><td><code>&quot;holiday&quot;</code> | <code>&quot;company_event&quot;</code></td></tr></tbody></table><p>Only <code>&quot;holiday&quot;</code> entries block PTO requests and are excluded from leave date ranges.</p><hr><h2 id="_13-rate-history-—-a-d" tabindex="-1">13. Rate_History — <code>A:D</code> <a class="header-anchor" href="#_13-rate-history-—-a-d" aria-label="Permalink to &quot;13. Rate_History — `A:D`&quot;">​</a></h2><p><strong>Written by</strong>: <code>set_rate</code> (append-only — never updates existing rows)</p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential.</td></tr><tr><td>B</td><td>1</td><td><code>user_id</code></td><td>integer</td><td>FK → <code>03. Users.id</code></td></tr><tr><td>C</td><td>2</td><td><code>hourly_cost</code></td><td>float</td><td>e.g. <code>80.00</code> for $80/hr</td></tr><tr><td>D</td><td>3</td><td><code>effective_from</code></td><td><code>YYYY-MM-DD</code></td><td>Rate applies from this date forward.</td></tr></tbody></table><p><strong>Lookup rule</strong>: for an entry dated <code>D</code>, use <code>MAX(effective_from) WHERE effective_from ≤ D</code>. This preserves historical P&amp;L accuracy when rates change.</p><p><strong>Example</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1, 5, 75.00, 2025-01-01</span></span>\n<span class="line"><span>2, 5, 85.00, 2026-03-01  ← rate increase from March 1st</span></span></code></pre></div><hr><h2 id="_14-liabilities-—-a-h" tabindex="-1">14. Liabilities — <code>A:H</code> <a class="header-anchor" href="#_14-liabilities-—-a-h" aria-label="Permalink to &quot;14. Liabilities — `A:H`&quot;">​</a></h2><p><strong>Written by</strong>: <code>create_liability</code><strong>Updated by</strong>: <code>cancel_liability</code> (F — status)</p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>id</code></td><td>integer</td><td>Sequential.</td></tr><tr><td>B</td><td>1</td><td><code>project_id</code></td><td>integer</td><td>FK → <code>02. Projects.id</code></td></tr><tr><td>C</td><td>2</td><td><code>vendor_user_id</code></td><td>integer</td><td>FK → <code>03. Users.id</code> (must be <code>employment_type=&quot;vendor&quot;</code>)</td></tr><tr><td>D</td><td>3</td><td><code>description</code></td><td>string</td><td>What this payment covers.</td></tr><tr><td>E</td><td>4</td><td><code>agreed_amount</code></td><td>float</td><td>Fixed payment in USD.</td></tr><tr><td>F</td><td>5</td><td><code>status</code></td><td>string</td><td><code>&quot;active&quot;</code> | <code>&quot;cancelled&quot;</code></td></tr><tr><td>G</td><td>6</td><td><code>created_by</code></td><td>integer</td><td>FK → <code>03. Users.id</code></td></tr><tr><td>H</td><td>7</td><td><code>created_at</code></td><td><code>YYYY-MM-DD</code></td><td></td></tr></tbody></table><p><strong>Example</strong>: <code>15, 12, 9, Dev House - Auth module, 5000, active, 1, 2026-03-15</code></p><hr><h2 id="_22-projects-master-—-a-i" tabindex="-1">22. Projects Master — <code>A:I</code> <a class="header-anchor" href="#_22-projects-master-—-a-i" aria-label="Permalink to &quot;22. Projects Master — `A:I`&quot;">​</a></h2><p><strong>Written by</strong>: <code>create_project</code>, <code>create_sprint</code>, <code>ensureProtectedProjects</code></p><blockquote><p>This sheet is joined to <code>02. Projects</code> <strong>by project name</strong> (not ID). The join is case-insensitive.</p></blockquote><p><strong>Bot-written columns (A–H):</strong></p><table tabindex="0"><thead><tr><th>Col</th><th>Idx</th><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>0</td><td><code>project_name</code></td><td>string</td><td>Join key to <code>02. Projects.name</code>.</td></tr><tr><td>B</td><td>1</td><td><code>client_name</code></td><td>string</td><td>Denormalised from <code>04. Clients.name</code>.</td></tr><tr><td>C</td><td>2</td><td><code>type</code></td><td>string</td><td><code>&quot;T&amp;M&quot;</code> | <code>&quot;Fixed Price&quot;</code> | <code>&quot;Retainer&quot;</code> | <code>&quot;Pro Bono&quot;</code> | <code>&quot;Agile&quot;</code> | <code>&quot;sprint&quot;</code></td></tr><tr><td>D</td><td>3</td><td><code>is_billable</code></td><td>boolean string</td><td><code>&quot;TRUE&quot;</code> or <code>&quot;FALSE&quot;</code>. Auto: <code>false</code> for Pro Bono.</td></tr><tr><td>E</td><td>4</td><td><code>contract_value</code></td><td>float or <code>&quot;&quot;</code></td><td>Total contract value in USD.</td></tr><tr><td>F</td><td>5</td><td><code>hours_budget</code></td><td>float or <code>&quot;&quot;</code></td><td>Annual hours (Retainer) or total hours (others).</td></tr><tr><td>G</td><td>6</td><td><code>status</code></td><td>string</td><td><code>&quot;Active&quot;</code> (capital A) — different from <code>02. Projects</code> which uses lowercase.</td></tr><tr><td>H</td><td>7</td><td><code>notes</code></td><td>string</td><td>Free text.</td></tr><tr><td>I</td><td>8</td><td><code>billing_rate</code></td><td>float or <code>&quot;&quot;</code></td><td>Blended hourly billing rate. User-managed in the sheet.</td></tr></tbody></table><blockquote><p><strong>Note</strong>: Columns I–O in the full reporting sheet version are user-formula columns (estimated hours, actual hours, variances). The bot writes only A–I. In reporting contexts, reference A:P for the full table.</p></blockquote>',83)])])}const g=d(c,[["render",a]]);export{p as __pageData,g as default};
